  const built=empty?`<p class="sx-emptyline">${sh(L('Пока нет — создайте первого.','None yet — create the first one.'))}</p>${a(L('Создать агента','Create an agent'),'simple-create','agent-form')}`:row('sp',L('работает','working'),L('Отвечает в поддержку по возвратам','Answering refund requests'),'Nicegram')+row('rl',L('давно не отзывался — 2 ч','not heard from — 2 h'),L('Работает над: «Заметки к выпуску 0.3.7»','Working on: “0.3.7 release notes”'),'Fabric')
  const view=st==='agent-view'?card('Claude Code',a(L('Консоль','Console'),'simple-agents','agent-view','p'),`<div class="sx-detail"><p>${sh(L('Сейчас: переделывает главную в новом стиле · Fabric · 12 мин','Now: rebuilding the home in the new style · Fabric · 12 min'))}</p><p class="sx-k">${sh(L('Последние действия','Recent acts'))}</p><ul><li>${sh(L('14:02 перенёс «Вход по почте» в «Готово»','14:02 moved “Email sign-in” to Done'))}</li><li>${sh(L('13:40 спросил вас о выпуске 0.3.7','13:40 asked you about the 0.3.7 release'))}</li></ul><p class="sx-k">${sh(L('Что получает агент','What the agent gets'))}</p><ul><li>${sh(L('Правила проекта и его задачи','The project’s rules and tasks'))}</li><li>${sh(L('Доску, вопросы к вам и память проекта','The board, questions for you and the project’s memory'))}</li><li>${sh(L('Работа только в папках проекта','Work only in the project’s folders'))}</li></ul></div>`):''
  const foot=off?act(`<b>${sh(L('Codex отключён','Codex disconnected'))}</b> · ${sh(L('консоли закрыты','consoles closed'))}`,'simple-agents','ready'):''
  return `<div class="sx-hello"><div><h2 tabindex="-1">${sh(L('Агенты','Agents'))}</h2><p>${sh(L('Все ваши агенты и что каждый делает. Консоль — в одно нажатие.','All your agents and what each does. A console is one press away.'))}</p></div><div class="sx-btns">${a(L('Создать агента','Create an agent'),'simple-create','agent-form','p')}</div></div>${view}${card(L('Агенты для кода на этом компьютере','Coding agents on this computer'),'',coding,'sx-wide')}${card(L('Агенты, созданные в Fabric','Agents built in Fabric'),'',built,'sx-wide')}${foot}`
